import sqlite3
import os
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT UNIQUE,
        name TEXT,
        quantity INTEGER,
        warehouse TEXT,
        last_audit TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        owner TEXT,
        scope TEXT,
        created_at TEXT
    )''')
    db.commit()
    db.close()

def verify_api_key(key):
    """Verify API key exists in database"""
    if not key:
        return False
    db = get_db()
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    return row is not None

@app.before_request
def authenticate():
    if request.endpoint == 'health':
        return None
    api_key = request.headers.get('X-API-Key')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/products/search')
def search_products():
    """Search products by warehouse and optional name filter"""
    warehouse = request.args.get('warehouse', '')
    name_filter = request.args.get('name', '')
    sort_col = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'quantity', 'sku', 'last_audit']
    if sort_col not in allowed_sorts:
        sort_col = 'name'

    db = get_db()

    # Build query with parameterized warehouse but dynamic name filter
    # for LIKE pattern support with user-controlled wildcards
    base_query = f"SELECT id, sku, name, quantity, warehouse FROM products WHERE warehouse = ? AND name LIKE '{name_filter}' ORDER BY {sort_col}"

    try:
        results = db.execute(base_query, (warehouse,)).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v1/products/<int:product_id>/audit', methods=['POST'])
def audit_product(product_id):
    """Record an audit timestamp for a product"""
    db = get_db()
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    db.execute('UPDATE products SET last_audit = ? WHERE id = ?', (timestamp, product_id))
    db.commit()
    return jsonify({'status': 'audited', 'timestamp': timestamp})

@app.route('/api/v1/products/bulk-import', methods=['POST'])
def bulk_import():
    """Import products from JSON payload"""
    data = request.get_json()
    if not data or 'products' not in data:
        return jsonify({'error': 'invalid payload'}), 400

    db = get_db()
    imported = 0
    for item in data['products']:
        try:
            db.execute(
                'INSERT OR REPLACE INTO products (sku, name, quantity, warehouse) VALUES (?, ?, ?, ?)',
                (item['sku'], item['name'], item['quantity'], item['warehouse'])
            )
            imported += 1
        except (KeyError, sqlite3.Error):
            continue
    db.commit()
    return jsonify({'imported': imported})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
